```tsx
import { useId } from "react";
import "./EmptyState.css";

export interface EmptyStateProps {
  title: string;
  message: string;
  actionLabel: string;
  onAction: () => void;
}

export function EmptyState({ title, message, actionLabel, onAction }: EmptyStateProps) {
  const titleId = useId();
  const messageId = useId();

  return (
    <section
      className="empty-state"
      aria-labelledby={titleId}
      aria-describedby={messageId}
    >
      <h2 id={titleId} className="empty-state__title">
        {title}
      </h2>
      <p id={messageId} className="empty-state__message">
        {message}
      </p>
      <button
        type="button"
        className="empty-state__action"
        onClick={onAction}
      >
        {actionLabel}
      </button>
    </section>
  );
}
```

```css
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  max-width: 36rem;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3rem) clamp(1rem, 3vw, 2rem);
  text-align: center;
  color: var(--ink);
  border: 1px solid var(--hair);
  border-radius: 12px;
}

.empty-state__title {
  margin: 0;
  font: inherit;
  font-size: clamp(1.125rem, 2.5vw, 1.5rem);
  font-weight: 600;
  color: var(--ink);
}

.empty-state__message {
  margin: 0;
  max-width: 40ch;
  font: inherit;
  font-size: clamp(0.9375rem, 1.8vw, 1.0625rem);
  line-height: 1.5;
  color: var(--muted);
}

.empty-state__action {
  margin-top: 0.5rem;
  padding: 0.6em 1.25em;
  font: inherit;
  font-size: clamp(0.9375rem, 1.8vw, 1rem);
  font-weight: 600;
  color: var(--slide);
  background: var(--myelin);
  border: none;
  border-radius: 999px;
  cursor: pointer;
  transition: box-shadow 150ms ease;
}

.empty-state__action:hover {
  box-shadow: 0 0 0 3px var(--myelin-wash);
}

:root[data-motion="reduce"] .empty-state__action {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .empty-state__action {
    transition: none;
  }
}
